// oc-gopatch is the helper that oc-run uses for the binaries the user downloads
// into the terminal. It classifies an ELF, starts a glibc program through the
// glibc loader with liboc-pathmap.so preloaded, patches a static Go program with
// the small oc-gosys runtime and then starts it, and passes everything else to
// the kernel unchanged.
//
// Build with CGO_ENABLED=0 for linux/arm64 and linux/x86_64. The oc-gosys blob is
// generated by native/gosys/build.sh into gosys_blob.go before the build.
package main

import (
	"fmt"
	"os"
)

const version = "1"

func usage() {
	fmt.Fprintln(os.Stderr, `usage:
  oc-gopatch classify FILE
  oc-gopatch patch SRC DST
  oc-gopatch run [--] COMMAND [ARG...]
  oc-gopatch version`)
}

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}
	switch os.Args[1] {
	case "classify":
		if len(os.Args) != 3 {
			usage()
			os.Exit(2)
		}
		kind, detail, err := classifyFile(os.Args[2])
		if err != nil {
			fmt.Fprintf(os.Stderr, "oc-gopatch: %v\n", err)
			os.Exit(1)
		}
		if detail != "" {
			fmt.Printf("%s %s\n", kind, detail)
		} else {
			fmt.Println(kind)
		}
	case "patch":
		if len(os.Args) != 4 {
			usage()
			os.Exit(2)
		}
		if err := patchFile(os.Args[2], os.Args[3]); err != nil {
			fmt.Fprintf(os.Stderr, "oc-gopatch: %v\n", err)
			os.Exit(1)
		}
	case "run":
		args := os.Args[2:]
		if len(args) > 0 && args[0] == "--" {
			args = args[1:]
		}
		if err := runCommand(args); err != nil {
			fmt.Fprintf(os.Stderr, "oc-gopatch: %v\n", err)
			os.Exit(1)
		}
	case "version":
		fmt.Println("oc-gopatch " + version)
	case "-h", "--help", "help":
		usage()
	default:
		usage()
		os.Exit(2)
	}
}
